{
  "kcs": [
    {
      "canonical_name": "数列极限",
      "aliases": ["数列收敛"],
      "description": "描述数列当n趋于无穷时趋近于某个常数的概念，用ε-N语言严格定义。"
    },
    {
      "canonical_name": "函数极限",
      "aliases": [],
      "description": "描述函数自变量趋近某点或无穷时函数值趋近于某常数的概念，用ε-δ语言定义。"
    },
    {
      "canonical_name": "无穷小量",
      "aliases": ["无穷小", "等价无穷小"],
      "description": "极限为0的变量，包含高阶、同阶、等价无穷小，用于极限计算与替换。"
    },
    {
      "canonical_name": "函数的连续性",
      "aliases": ["连续函数", "间断点"],
      "description": "函数在某点极限值等于函数值的性质，包括间断点分类与闭区间上连续性质。"
    },
    {
      "canonical_name": "导数",
      "aliases": ["微商"],
      "description": "函数在某点的瞬时变化率，几何意义为切线斜率，物理意义为瞬时速度。"
    },
    {
      "canonical_name": "基本初等函数导数表",
      "aliases": ["导数表", "基本导数公式"],
      "description": "常见初等函数（幂、指、对、三角等）的导数公式汇总。"
    },
    {
      "canonical_name": "求导法则",
      "aliases": ["导数的四则运算", "复合函数求导", "链式法则", "反函数求导"],
      "description": "导数运算规则，包括四则、复合函数链式法则及反函数求导。"
    },
    {
      "canonical_name": "高阶导数",
      "aliases": ["高阶导"],
      "description": "对函数多次求导得到的导数，表示变化率的变化率。"
    },
    {
      "canonical_name": "隐函数求导",
      "aliases": [],
      "description": "对方程确定的隐函数直接求导的方法，无需显化函数表达式。"
    },
    {
      "canonical_name": "罗尔定理",
      "aliases": ["Rolle定理"],
      "description": "若函数在闭区间连续、开区间可导且端点值相等，则存在内点导数为零。"
    },
    {
      "canonical_name": "拉格朗日中值定理",
      "aliases": ["拉格朗日定理", "微分中值定理"],
      "description": "若函数在闭区间连续、开区间可导，则存在内点导数值等于平均变化率。"
    },
    {
      "canonical_name": "柯西中值定理",
      "aliases": ["Cauchy中值定理"],
      "description": "两个函数在满足条件下，存在内点使导数比等于函数改变量比。"
    },
    {
      "canonical_name": "洛必达法则",
      "aliases": ["L'Hospital法则"],
      "description": "用于计算0/0或∞/∞型极限，通过分子分母分别求导再求极限。"
    },
    {
      "canonical_name": "泰勒公式",
      "aliases": ["泰勒展开", "Taylor公式", "麦克劳林公式"],
      "description": "用多项式逼近可微函数，包括佩亚诺余项和拉格朗日余项。"
    },
    {
      "canonical_name": "不定积分",
      "aliases": ["原函数", "反导数"],
      "description": "导数的逆运算，求函数的原函数族，含基本积分表。"
    },
    {
      "canonical_name": "换元积分法",
      "aliases": ["变量代换"],
      "description": "通过变量替换简化积分计算的方法，分第一类与第二类换元。"
    },
    {
      "canonical_name": "分部积分法",
      "aliases": [],
      "description": "利用乘积求导法则将积分转化为另一积分，适用于乘积函数积分。"
    },
    {
      "canonical_name": "定积分",
      "aliases": ["黎曼积分"],
      "description": "函数在区间上积分和的极限，定义为曲边梯形面积，含性质与计算。"
    },
    {
      "canonical_name": "牛顿-莱布尼茨公式",
      "aliases": ["微积分基本定理"],
      "description": "将定积分与不定积分连接，通过原函数差值计算定积分。"
    },
    {
      "canonical_name": "定积分的应用",
      "aliases": [],
      "description": "用定积分求解平面面积、旋转体体积、弧长等几何与物理问题。"
    }
  ],
